mapper.select:
	 /** give-operation-mapper.getGiveOperationTotalCnt (기부 금액, 사용 금액 합계) */
	 SELECT NVL(CNTR_AMT, 0) AS CNTR_AMT
	 		,NVL(EXPNDTR_AMT, 0) AS EXPNDTR_AMT
	 		,NVL(CNTR_AMT,0) - NVL(EXPNDTR_AMT,0) AS BALANCE_AMT
	   FROM ( SELECT ( SELECT SUM(CNTR_AMT) AS CNTR_AMT
	                     FROM G_CNTR
	                    WHERE 1=1
      					  AND DELETE_AT = 'N'
        				  AND CNTR_STTUS_CODE = '200'
        				  AND STTEMNT_PAY_DE IS NOT NULL

						  	AND CNTR_LOCGOV_CODE = #{shLocgovCode}

        			 ) AS CNTR_AMT
        			 ,(SELECT SUM(EXPNDTR_AMT)
        			     FROM G_CTBNY_OPRATN
        			    WHERE 1=1

							AND LOCGOV_CODE = #{shLocgovCode}


							AND REGIST_SN != #{registSn}

        			    ) AS EXPNDTR_AMT
            )

/** give-operation-mapper.getGiveOperationListTotalCnt (기부금 운용정보 리스트 총개수) */ SELECT COUNT(1) AS CNT FROM G_LOCGOV GL INNER JOIN ( SELECT YEAR(GC.STTEMNT_PAY_DE) AS CNTR_YEAR ,CNTR_LOCGOV_CODE ,SUM(CNTR_AMT) AS CNTR_AMT FROM G_CNTR GC WHERE 1=1 AND GC.DELETE_AT = 'N' AND GC.CNTR_STTUS_CODE = '200' AND GC.STTEMNT_PAY_DE IS NOT NULL
AND GC.CNTR_LOCGOV_CODE = #{shLocgovCode}
AND YEAR(GC.STTEMNT_PAY_DE) = #{shCntrYear}
GROUP BY YEAR(GC.STTEMNT_PAY_DE), CNTR_LOCGOV_CODE ) GC ON GL.LOCGOV_CODE = GC.CNTR_LOCGOV_CODE WHERE 1=1
AND GL.LOCGOV_CODE = #{shLocgovCode}
AND GC.CNTR_YEAR = #{shCntrYear}

/** give-operation-mapper.getGiveOperationList (기부금 운용정보 리스트) */
SELECT GC.CNTR_YEAR ,GL.UPPER_LOCGOV_CODE ,(SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = GL.UPPER_LOCGOV_CODE AND CODE_TYPE = 'WDR' AND USE_YN = 'Y') AS UPPER_LOCGOV_NM ,GL.LOCGOV_CODE ,GL.LOCGOV_NM AS LOCGOV_NM ,NVL(GC.CNTR_AMT, 0) AS CNTR_AMT ,NVL(GCO.EXPNDTR_AMT, 0) AS EXPNDTR_AMT ,NVL(GC.CNTR_AMT,0) - NVL(GCO.EXPNDTR_AMT,0) AS BALANCE_AMT FROM G_LOCGOV GL INNER JOIN ( SELECT YEAR(GC.STTEMNT_PAY_DE) AS CNTR_YEAR ,CNTR_LOCGOV_CODE ,SUM(CNTR_AMT) AS CNTR_AMT FROM G_CNTR GC WHERE 1=1 AND GC.DELETE_AT = 'N' AND GC.CNTR_STTUS_CODE = '200' AND GC.STTEMNT_PAY_DE IS NOT NULL
AND GC.CNTR_LOCGOV_CODE = #{shLocgovCode}
AND YEAR(GC.STTEMNT_PAY_DE) = #{shCntrYear}
GROUP BY YEAR(GC.STTEMNT_PAY_DE), CNTR_LOCGOV_CODE ) GC ON GL.LOCGOV_CODE = GC.CNTR_LOCGOV_CODE LEFT OUTER JOIN ( SELECT YEAR(EXPNDTR_DE) AS CNTR_YEAR ,LOCGOV_CODE ,SUM(EXPNDTR_AMT) AS EXPNDTR_AMT FROM G_CTBNY_OPRATN WHERE 1=1
AND LOCGOV_CODE = #{shLocgovCode}
AND YEAR(EXPNDTR_DE) = #{shCntrYear}
GROUP BY YEAR(EXPNDTR_DE), LOCGOV_CODE ) GCO ON GC.CNTR_YEAR = GCO.CNTR_YEAR AND GC.CNTR_LOCGOV_CODE = GCO.LOCGOV_CODE WHERE 1=1
AND GL.LOCGOV_CODE = #{shLocgovCode}
AND GC.CNTR_YEAR = #{shCntrYear}
ORDER BY GC.CNTR_YEAR DESC, GL.UPPER_LOCGOV_CODE, GL.LOCGOV_CODE

/** give-operation-mapper.getCtbnyOpratnListTotalCnt (기부금 사용정보 리스트) */ SELECT COUNT(1) AS CNT FROM G_CTBNY_OPRATN GCO INNER JOIN OP_USER OU ON GCO.FRST_REGISTER_ID = OU.USER_ID LEFT OUTER JOIN OP_COMMON_CODE OCC ON CODE_TYPE = 'CNTR_USE' AND OCC.ID = GCO.BSNS_PURPS_CODE WHERE 1=1
AND GCO.LOCGOV_CODE = #{shLocgovCode}
AND GCO.EXPNDTR_DE >= #{shCntrDeStart}
AND GCO.EXPNDTR_DE <= #{shCntrDeEnd}
AND GCO.BSNS_NM LIKE CONCAT('%', #{searchTxt} , '%')
AND OCC.LABEL LIKE CONCAT('%', #{searchTxt} , '%')
AND GCO.BSNS_CN LIKE CONCAT('%', #{searchTxt} , '%')
AND ( GCO.BSNS_NM LIKE CONCAT('%', #{searchTxt} , '%') OR OCC.LABEL LIKE CONCAT('%', #{searchTxt} , '%') OR GCO.BSNS_CN LIKE CONCAT('%', #{searchTxt} , '%') )

/** give-operation-mapper.getCtbnyOpratnList (기부금 사용정보 리스트) */
SELECT A.regist_sn ,A.locgov_code ,A.bsns_purps_code ,A.bsns_purps_nm ,A.expndtr_amt ,A.bsns_nm ,A.bsns_cn ,A.file_cnt ,A.login_id AS login_id ,A.user_name AS user_name ,A.user_id ,A.expndtr_de FROM ( SELECT regist_sn ,GCO.locgov_code ,GCO.bsns_purps_code ,NVL(OCC.label,'') AS bsns_purps_nm ,NVL(GCO.expndtr_amt,0) AS expndtr_amt ,GCO.bsns_nm ,GCO.bsns_cn ,NVL((SELECT COUNT(1) FROM G_CTBNY_OPRATN_FILE GCOF WHERE GCOF.regist_sn = GCO.regist_sn),0) AS file_cnt ,OU.login_id ,OU.user_name ,OU.user_id ,date_format(GCO.expndtr_de, '%Y-%m-%d') AS expndtr_de FROM G_CTBNY_OPRATN GCO INNER JOIN OP_USER OU ON GCO.frst_register_id = OU.user_id LEFT OUTER JOIN OP_COMMON_CODE OCC ON code_type = 'CNTR_USE' AND OCC.id = GCO.BSNS_PURPS_CODE WHERE 1=1
AND GCO.locgov_code = #{shLocgovCode}
AND GCO.expndtr_de >= #{shCntrDeStart}
AND GCO.expndtr_de <= #{shCntrDeEnd}
AND GCO.bsns_nm LIKE CONCAT('%', #{searchTxt} , '%')
AND OCC.label LIKE CONCAT('%', #{searchTxt} , '%')
AND GCO.bsns_cn LIKE CONCAT('%', #{searchTxt} , '%')
AND ( GCO.bsns_nm LIKE CONCAT('%', #{searchTxt} , '%') OR OCC.label LIKE CONCAT('%', #{searchTxt} , '%') OR GCO.bsns_cn LIKE CONCAT('%', #{searchTxt} , '%') )
) A ORDER BY A.expndtr_de DESC

/** give-operation-mapper.getCtbnyOpratnListAmt (기부금 운용정보 사용금액 합계) */ SELECT NVL(SUM(NVL(GCO.EXPNDTR_AMT,0)), 0) AS EXPNDTR_AMT FROM G_CTBNY_OPRATN GCO INNER JOIN OP_USER OU ON GCO.FRST_REGISTER_ID = OU.USER_ID LEFT OUTER JOIN OP_COMMON_CODE OCC ON CODE_TYPE = 'CNTR_USE' AND OCC.ID = GCO.BSNS_PURPS_CODE WHERE 1=1
AND GCO.LOCGOV_CODE = #{shLocgovCode}
AND GCO.EXPNDTR_DE >= #{shCntrDeStart}
AND GCO.EXPNDTR_DE <= #{shCntrDeEnd}
AND GCO.BSNS_NM LIKE CONCAT('%', #{searchTxt} , '%')
AND OCC.LABEL LIKE CONCAT('%', #{searchTxt} , '%')
AND GCO.BSNS_CN LIKE CONCAT('%', #{searchTxt} , '%')
AND ( GCO.BSNS_NM LIKE CONCAT('%', #{searchTxt} , '%') OR OCC.LABEL LIKE CONCAT('%', #{searchTxt} , '%') OR GCO.BSNS_CN LIKE CONCAT('%', #{searchTxt} , '%') )

mapper.insert:
/** give-operation-mapper.insertCtbnyOpratn (기부금 운용정보 사용정보 등록) */

	SELECT NVL(MAX(REGIST_SN), 0) + 1 AS REGIST_SN
	  FROM G_CTBNY_OPRATN

INSERT INTO G_CTBNY_OPRATN (
	REGIST_SN
	,LOCGOV_CODE
	,BSNS_PURPS_CODE
	,BSNS_NM
	,BSNS_CN
	,EXPNDTR_DE
	,EXPNDTR_AMT
	,FRST_REGISTER_ID
	,FRST_REGIST_PNTTM
	,LAST_UPDUSR_ID
	,LAST_UPDT_PNTTM
	,RM
) VALUES (
	#{registSn}
	,#{locgovCode}
	,#{bsnsPurpsCode}
	,#{bsnsNm}
	,#{bsnsCn}
	,#{expndtrDe}
	,#{expndtrAmt}
	,#{frstRegisterId}
	,
	,#{frstRegisterId}
	,
	,#{rm}
)

/** give-operation-mapper.insertCtbnyOpratn (기부금 운용정보 사용정보 등록) */

	SELECT NVL(MAX(REGIST_FILE_ID), 0) + 1 AS REGIST_FILE_ID
	  FROM G_CTBNY_OPRATN_FILE

INSERT INTO G_CTBNY_OPRATN_FILE (
	REGIST_FILE_ID
	,REGIST_SN
	,FILE_NM
	,ORGINL_FILE_NM
	,FILE_TY
	,SORT_ORDR
	,FRST_REGISTER_ID
	,FRST_REGIST_PNTTM
	,LAST_UPDUSR_ID
	,LAST_UPDT_PNTTM
) VALUES (
	#{registFileId}
	,#{registSn}
	,#{fileNm}
	,#{orginlFileNm}
	,#{fileTy}
	,( SELECT NVL(MAX(SORT_ORDR),0) + 1 AS SORT_ORDR FROM G_CTBNY_OPRATN_FILE WHERE REGIST_SN = #{registSn} )
	,#{frstRegisterId}
	,
	,#{lastUpdusrId}
	,
)

mapper.delete:
/** give-operation-mapper.deleteCtbnyOpratnFile (기부금 운용정보 파일 삭제) */
DELETE
  FROM G_CTBNY_OPRATN_FILE
 WHERE 1 = 1

	   AND REGIST_FILE_ID = #{registFileId}


	   AND REGIST_SN = #{registSn}

mapper.update:
/** give-operation-mapper.updateCtbnyOpratn (기부금 운용정보 수정) */
UPDATE G_CTBNY_OPRATN
   SET BSNS_PURPS_CODE = #{bsnsPurpsCode}
       ,BSNS_NM = #{bsnsNm}
       ,BSNS_CN = #{bsnsCn}
       ,EXPNDTR_DE = #{expndtrDe}
       ,EXPNDTR_AMT = #{expndtrAmt}
       ,LAST_UPDUSR_ID = #{lastUpdusrId}
       ,LAST_UPDT_PNTTM = 
       ,RM = #{rm}
 WHERE REGIST_SN = #{registSn}

mapper.delete:
/** give-operation-mapper.deleteCtbnyOpratn (기부금 운용정보 삭제) */
DELETE
  FROM G_CTBNY_OPRATN
 WHERE REGIST_SN = #{registSn}
